import React, { useEffect } from "react";
import Layout from "../components/Layout";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import { graphql, type HeadFC, type PageProps, Link } from "gatsby";
import images from "../images";
import SEO from "../components/seo";
import I18nHeadProvider from "../components/I18nHeadProvider";
import AuditRequestForm from "../components/AuditRequestForm";
import {
  buildBreadcrumbListSchema,
  localizeSitePath,
} from "../utils/structuredData";
import { buildMailtoHref } from "../utils/mailto";
import { trackCtaClick } from "../utils/analytics";
import {
  buildContactIntentPath,
  getContactIntentFromSearch,
  type JourneyCtaType,
} from "../utils/cta";

import { BiLogoInstagramAlt } from "react-icons/bi";
import {
  FaSquareFacebook,
  FaSquareWhatsapp,
  FaSquarePhone,
  FaLinkedin,
} from "react-icons/fa6";
import { MdEmail } from "react-icons/md";
import { ImLocation2 } from "react-icons/im";
import ContactForm from "../components/contactForm";

const info: Company = data[0];

type ContactIntentMeta = {
  label: string;
  description: string;
  submitLabel: string;
};

const ContactPage: React.FC<PageProps> = ({ location }) => {
  const { t } = useTranslation();
  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const mailto = buildMailtoHref(info.email, {
    subject: t("contact.meta.emailSubject") as string,
    body: t("contact.meta.emailBody") as string,
  });

  const tel = `tel:${info.phone}`;
  const whatsappHref = info.whatsapp;
  const activeIntent =
    getContactIntentFromSearch(location?.search) || "quote";
  const activeIntentMetaRaw = t(`journeyCtas.types.${activeIntent}`, {
    returnObjects: true,
  }) as unknown;
  const activeIntentMeta =
    activeIntentMetaRaw &&
    typeof activeIntentMetaRaw === "object" &&
    "label" in activeIntentMetaRaw &&
    "description" in activeIntentMetaRaw &&
    "submitLabel" in activeIntentMetaRaw
      ? (activeIntentMetaRaw as ContactIntentMeta)
      : {
          label: t(`journeyCtas.types.${activeIntent}.label`) as string,
          description: t(`journeyCtas.types.${activeIntent}.description`) as string,
          submitLabel: t(`journeyCtas.types.${activeIntent}.submitLabel`) as string,
        };
  const trustItemsRaw = t("contact.hero.trustItems", {
    returnObjects: true,
    defaultValue: [],
  }) as unknown;
  const trustItems = Array.isArray(trustItemsRaw) ? trustItemsRaw : [];
  const requestIncludeItemsRaw = t("contact.request.include.items", {
    returnObjects: true,
    defaultValue: [],
  }) as unknown;
  const requestIncludeItems = Array.isArray(requestIncludeItemsRaw)
    ? requestIncludeItemsRaw
    : [];
  const requestOutcomeItemsRaw = t("contact.request.outcome.items", {
    returnObjects: true,
    defaultValue: [],
  }) as unknown;
  const requestOutcomeItems = Array.isArray(requestOutcomeItemsRaw)
    ? requestOutcomeItemsRaw
    : [];
  const formalCards = [
    {
      intent: "audit" as JourneyCtaType,
      title: t("contact.cards.audit.title") as string,
      text: t("contact.cards.audit.text") as string,
      cta: t("contact.cards.audit.jumpCta") as string,
      href: buildContactIntentPath("audit"),
      variant: "gradient-reverse",
    },
    {
      intent: "quote" as JourneyCtaType,
      title: t("contact.cards.quote.title") as string,
      text: t("contact.cards.quote.text") as string,
      cta: t("contact.cards.quote.cta") as string,
      href: buildContactIntentPath("quote"),
      variant: "gradient",
    },
    {
      intent: "maintenance" as JourneyCtaType,
      title: t("contact.cards.maintenance.title") as string,
      text: t("contact.cards.maintenance.text") as string,
      cta: t("contact.cards.maintenance.cta") as string,
      href: buildContactIntentPath("maintenance"),
      variant: "gradient-reverse",
    },
    {
      intent: "strategicReview" as JourneyCtaType,
      title: t("contact.cards.strategicReview.title") as string,
      text: t("contact.cards.strategicReview.text") as string,
      cta: t("contact.cards.strategicReview.cta") as string,
      href: buildContactIntentPath("strategicReview"),
      variant: "gradient",
    },
  ];

  return (
    <Layout data={info} bgImage={images.bg_carousel_1.src}>
      <section className={styles.wrapper}>
        {/* HERO */}
        <header className="text-center">
          <h1 className={styles.title}>{t("contact.hero.title")}</h1>
          <p className={styles.subtitle}>{t("contact.hero.subtitle")}</p>

          <div className={styles.ctaRow}>
            <a
              href="#contact-quick"
              className={`${styles.ctaButton} bg-secondary`}
              onClick={() => {
                void trackCtaClick({
                  cta_name: "contact_hero_quick",
                  cta_location: "contact_hero",
                  destination: "#contact-quick",
                  destination_type: "internal",
                });
              }}
            >
              {t("contact.hero.primaryCta")}
            </a>

            <Link
              to={buildContactIntentPath(activeIntent)}
              className={`${styles.ctaButton} ${styles.ctaButtonSecondary} bg-purplesemilight`}
              onClick={() => {
                void trackCtaClick({
                  cta_name: `contact_hero_${activeIntent}`,
                  cta_location: "contact_hero",
                  destination: buildContactIntentPath(activeIntent),
                  destination_type: "internal",
                });
              }}
            >
              {t("contact.hero.secondaryCta")}
            </Link>
          </div>

          <p className={styles.helper}>{t("contact.hero.helper")}</p>

          {Array.isArray(trustItems) && trustItems.length > 0 ? (
            <div className="mt-6 flex flex-wrap items-center justify-center gap-2">
              {trustItems.map((item) => (
                <span
                  key={item}
                  className="rounded-full border border-white/15 bg-white/10 px-3 py-1 text-xs sm:text-sm text-light/85"
                >
                  {item}
                </span>
              ))}
            </div>
          ) : null}
        </header>

        <section id="contact-quick" className="mt-10 scroll-mt-28">
          <div className="text-center">
            <p className={styles.sectionEyebrow}>{t("contact.quick.eyebrow")}</p>
            <h2 className={styles.sectionTitleAlt}>{t("contact.quick.title")}</h2>
            <p className={styles.bottomText}>{t("contact.quick.subtitle")}</p>
          </div>

          <div className="mt-6 grid grid-cols-1 sm:grid-cols-2 gap-4">
            <article className={`${styles.card} gradient-reverse`}>
              <h3 className={styles.cardTitle}>{t("contact.quick.whatsapp.title")}</h3>
              <p className={styles.cardText}>{t("contact.quick.whatsapp.text")}</p>
              <a
                href={whatsappHref}
                target="_blank"
                rel="noreferrer"
                className={styles.cardLink}
              >
                {t("contact.quick.whatsapp.cta")}
              </a>
            </article>

            <article className={`${styles.card} gradient`}>
              <h3 className={styles.cardTitle}>{t("contact.quick.email.title")}</h3>
              <p className={styles.cardText}>{t("contact.quick.email.text")}</p>
              <a href={mailto} className={styles.cardLink}>
                {t("contact.quick.email.cta")}
              </a>
            </article>
          </div>
        </section>

        {/* FORMAL OPTIONS */}
        <section id="contact-options" className="mt-12 scroll-mt-28">
          <div className="text-center">
            <p className={styles.sectionEyebrow}>{t("contact.formal.eyebrow")}</p>
            <h2 className={styles.sectionTitleAlt}>{t("contact.formal.title")}</h2>
            <p className={styles.bottomText}>{t("contact.formal.subtitle")}</p>
          </div>

          <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 gap-4">
            {formalCards.map((card) => {
              const isActive = card.intent === activeIntent;

              return (
                <article
                  key={card.intent}
                  id={card.intent === "audit" ? "contact-audit" : undefined}
                  className={`${styles.card} ${card.variant} ${isActive ? styles.cardActive : ""}`}
                >
                  <h3 className={styles.cardTitle}>{card.title}</h3>
                  <p className={styles.cardText}>{card.text}</p>

                  {card.intent === "audit" ? (
                    <>
                      <AuditRequestForm mailto={mailto} />
                      <a href={card.href} className={styles.cardLink}>
                        {card.cta}
                      </a>
                    </>
                  ) : (
                    <a href={card.href} className={styles.cardLink}>
                      {card.cta}
                    </a>
                  )}
                </article>
              );
            })}
          </div>
        </section>

        {/* REQUEST FORM */}
        <section id="contact-request-form" className="mt-12 scroll-mt-28">
          <div className={`${styles.requestBanner} gradient`}>
            <p className={styles.sectionEyebrow}>{t("contact.request.eyebrow")}</p>
            <h2 className={styles.sectionTitleAlt}>
              {t("contact.request.title", { intent: activeIntentMeta.label })}
            </h2>
            <p className={styles.bottomText}>{activeIntentMeta.description}</p>

            <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4 text-left">
              <div className={styles.requestInfoCard}>
                <h3 className={styles.cardTitle}>{t("contact.request.include.title")}</h3>
                <ul className="mt-4 list-disc pl-5 space-y-2 text-sm text-light/80">
                  {requestIncludeItems.map((item) => (
                    <li key={item}>{item}</li>
                  ))}
                </ul>
              </div>

              <div className={styles.requestInfoCard}>
                <h3 className={styles.cardTitle}>{t("contact.request.outcome.title")}</h3>
                <ul className="mt-4 list-disc pl-5 space-y-2 text-sm text-light/80">
                  {requestOutcomeItems.map((item) => (
                    <li key={item}>{item}</li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        </section>

        {/* FORM */}
        <article className={styles.infoBlock}>
          <div className={`${styles.socialContainer} gradient`}>
            <ContactForm
              leadIntent={activeIntent}
              intro={t("contact.request.formIntro", {
                intent: activeIntentMeta.label,
              }) as string}
              submitLabel={activeIntentMeta.submitLabel}
            />
          </div>

          <div className={`${styles.socialContainer} gradient-reverse`}>
            <h3 className={styles.sectionTitle}>{t("contact.details.title")}</h3>

            <section className={`${styles.links} flex-col`}>
              <a href={tel} className={styles.inlineLinks}>
                <FaSquarePhone />
                <span>{info.phone}</span>
              </a>

              <a href={mailto} className={styles.inlineLinks}>
                <MdEmail />
                <span>{info.email}</span>
              </a>

              <div className={styles.inlineLinks}>
                <ImLocation2 />
                <span>
                  {info.city}, {info.province}, {info.country}
                </span>
              </div>

              <p className={styles.smallNote}>{t("contact.details.note")}</p>
            </section>

            <h3 className={`${styles.sectionTitle} mt-12`}>{t("contact.social.title")}</h3>
            <p className={styles.smallNote}>{t("contact.social.note")}</p>

            <section className={styles.links}>
              <a
                href={info.instagram}
                target="_blank"
                rel="noreferrer"
                className={styles.iconWrapper}
                aria-label="Instagram"
              >
                <BiLogoInstagramAlt className={styles.icon} />
              </a>
              <a
                href={info.facebook}
                target="_blank"
                rel="noreferrer"
                className={styles.iconWrapper}
                aria-label="Facebook"
              >
                <FaSquareFacebook className={styles.icon} />
              </a>
              <a
                href={whatsappHref}
                target="_blank"
                rel="noreferrer"
                className={styles.iconWrapper}
                aria-label="WhatsApp"
              >
                <FaSquareWhatsapp className={styles.icon} />
              </a>
              <a
                href={info.linkedin}
                target="_blank"
                rel="noreferrer"
                className={styles.iconWrapper}
                aria-label="LinkedIn"
              >
                <FaLinkedin className={styles.icon} />
              </a>
            </section>
          </div>
        </article>

        {/* SEO-friendly closing */}
        <section className="mt-12 text-center">
          <h2 className={styles.sectionTitleAlt}>{t("contact.bottom.title")}</h2>
          <p className={styles.bottomText}>{t("contact.bottom.text")}</p>
        </section>
      </section>
    </Layout>
  );
};

const ContactHeadContent: React.FC = () => {
  const { t } = useTranslation();
  const { language, defaultLanguage } = useI18next();
  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home") as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t("menu.contact") as string,
      path: localizeSitePath("/contact/", language, defaultLanguage),
    },
  ]);

  return (
    <SEO
      data={info}
      titleKey="contact.metaTitle"
      descriptionKey="contact.metaDescription"
      pathname="/contact/"
      schemaType="ProfessionalService"
      includeLocalBusinessDetails
      pageSchemaType="ContactPage"
      additionalSchemas={breadcrumbSchema ? [breadcrumbSchema] : undefined}
    />
  );
};

export const Head: HeadFC = ({ data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <ContactHeadContent />
  </I18nHeadProvider>
);

export default ContactPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  wrapper: "w-full max-w-4xl mx-auto text-center text-purplelight px-4 sm:px-0 py-10",
  title: "text-3xl sm:text-5xl poppins-bold text-light",
  subtitle: "text-lg sm:text-2xl poppins-regular text-light/90 mt-4",
  helper: "text-sm sm:text-base text-light/70 mt-6 max-w-3xl mx-auto",
  ctaRow: "mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3",

  ctaButton:
    "rounded-full px-5 py-2.5 text-light text-center transition duration-[400ms] hover:opacity-90",
  ctaButtonSecondary: "text-dark font-semibold",

  cardsGrid: "grid grid-cols-1 sm:grid-cols-3 gap-4",
  card: "rounded-3xl p-6 sm:p-8 text-left",
  cardTitle: "text-xl font-semibold text-light",
  cardText: "text-sm sm:text-base text-light/80 mt-3 leading-relaxed",
  cardLink: "inline-block mt-5 text-sm text-light underline underline-offset-4 hover:opacity-90",

  infoBlock: "flex flex-col sm:flex-row justify-center gap-4 mt-10",
  socialContainer: "rounded-3xl py-10 px-8 text-left",
  sectionTitle: "text-2xl poppins-regular text-light",
  sectionTitleAlt: "text-2xl sm:text-3xl poppins-regular text-verde",
  sectionEyebrow: "text-xs font-semibold uppercase tracking-[0.14em] text-secondary",
  smallNote: "text-sm text-light/70 mt-4 leading-relaxed",
  links: "hidden sm:flex gap-4 text-purplesemilight justify-start mt-6 text-2xl",
  iconWrapper:
    "block p-4 rounded-full bg-purplelight hover:bg-purplesemilight hover:text-purplelight transition duration-[600ms]",
  inlineLinks: "flex flex-row items-center gap-2 text-light/90 text-base",
  icon: "text-[3rem] sm:text-[4rem]",
  cardActive: "ring-2 ring-secondary/60",
  requestBanner: "rounded-3xl p-6 sm:p-8 text-left",
  requestInfoCard: "rounded-2xl border border-white/15 bg-white/5 p-5",
  bottomText: "text-sm sm:text-base text-light/70 mt-4 max-w-3xl mx-auto",
};
