import React, { useState } from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
// import emailjs from "@emailjs/browser";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import { db } from "../../firebaseConfig";
// import { buildEmailMessage, getEmailJsConfig } from "../../utils/emailjs";
import { trackLeadCapture } from "../utils/analytics";

type Props = {
  mailto: string;
};

const AuditRequestForm: React.FC<Props> = ({ mailto }) => {
  const { t } = useTranslation();
  const [auditSending, setAuditSending] = useState(false);
  const [auditSent, setAuditSent] = useState(false);
  const [auditError, setAuditError] = useState("");
  const [auditForm, setAuditForm] = useState({
    fullName: "",
    email: "",
    website: "",
    goal: "",
  });

  const handleAuditChange = (
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = event.target;
    setAuditForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleAuditSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setAuditSending(true);
    setAuditError("");

    const auditMessage = [
      "Audit request",
      `Website URL: ${auditForm.website || "-"}`,
      `Goal: ${auditForm.goal || "-"}`,
    ].join("\n");

    try {
      await addDoc(collection(db, "freeAudit"), {
        fullName: auditForm.fullName,
        email: auditForm.email,
        website: auditForm.website,
        goal: auditForm.goal,
        message: auditMessage,
        createdAt: Timestamp.now(),
      });

      // const emailConfig = getEmailJsConfig();
      // if (!emailConfig) {
      //   setAuditError(t("contact.cards.audit.error") || "Missing EmailJS configuration.");
      //   return;
      // }

      // const emailMessage = buildEmailMessage("contact", {
      //   fullName: auditForm.fullName,
      //   email: auditForm.email,
      //   message: auditMessage,
      // });

      // await emailjs.send(
      //   emailConfig.serviceId,
      //   emailConfig.templateId,
      //   emailMessage,
      //   emailConfig.publicKey
      // );

      await trackLeadCapture({
        form_name: "audit_request_form",
        lead_type: "audit_request",
        method: "form_submit",
      });

      setAuditSent(true);
      setAuditForm({
        fullName: "",
        email: "",
        website: "",
        goal: "",
      });
    } catch (error) {
      console.error("Error submitting audit form:", error);
      setAuditError(t("contact.cards.audit.error") || "Error sending request.");
    } finally {
      setAuditSending(false);
    }
  };

  return (
    <>
      {auditSent ? (
        <p className={styles.auditSuccess}>
          {t("contact.cards.audit.success")}
        </p>
      ) : (
        <form onSubmit={handleAuditSubmit} className="mt-5">
          <label className={styles.auditLabel} htmlFor="audit-fullName">
            {t("contact.cards.audit.form.name")}
          </label>
          <input
            id="audit-fullName"
            name="fullName"
            type="text"
            autoComplete="name"
            required
            value={auditForm.fullName}
            onChange={handleAuditChange}
            className={styles.auditInput}
          />

          <label className={styles.auditLabel} htmlFor="audit-email">
            {t("contact.cards.audit.form.email")}
          </label>
          <input
            id="audit-email"
            name="email"
            type="email"
            autoComplete="email"
            required
            value={auditForm.email}
            onChange={handleAuditChange}
            className={styles.auditInput}
          />

          <label className={styles.auditLabel} htmlFor="audit-website">
            {t("contact.cards.audit.form.website")}
          </label>
          <input
            id="audit-website"
            name="website"
            type="url"
            placeholder="https://"
            value={auditForm.website}
            onChange={handleAuditChange}
            className={styles.auditInput}
          />

          <label className={styles.auditLabel} htmlFor="audit-goal">
            {t("contact.cards.audit.form.goal")}
          </label>
          <textarea
            id="audit-goal"
            name="goal"
            rows={3}
            value={auditForm.goal}
            onChange={handleAuditChange}
            className={`${styles.auditInput} ${styles.auditTextarea}`}
          />

          <button
            type="submit"
            disabled={auditSending}
            className={`${styles.auditSubmit} ${
              auditSending ? "opacity-60 cursor-not-allowed" : ""
            }`}
          >
            {auditSending
              ? t("contact.cards.audit.form.sending")
              : t("contact.cards.audit.form.submit")}
          </button>

          {auditError ? <p className={styles.auditError}>{auditError}</p> : null}
        </form>
      )}

      <p className="mt-4 text-xs text-light/70">
        {t("contact.cards.audit.fallbackLabel")}{" "}
        <a href={mailto} className="underline underline-offset-4">
          {t("contact.cards.audit.cta")}
        </a>
      </p>
    </>
  );
};

export default AuditRequestForm;

const styles = {
  auditLabel: "mt-4 block text-xs text-light/70",
  auditInput:
    "mt-2 w-full rounded-xl border border-purplesemilight/50 bg-primary/70 px-4 py-2.5 text-sm text-light placeholder:text-purplelight/60 focus:outline-none focus:border-secondary focus:ring-2 focus:ring-secondary/40 transition",
  auditTextarea: "resize-y",
  auditSubmit:
    "mt-4 w-full rounded-full bg-secondary px-5 py-2.5 text-light text-sm text-center transition duration-[400ms] hover:opacity-90",
  auditSuccess: "mt-5 text-sm text-light/80",
  auditError: "mt-3 text-xs text-purplelight",
};
