const WRAPPING_QUOTES = /^["'“”‘’]+|["'“”‘’]+$/g;

function cleanMailtoField(value?: string | null) {
  return String(value ?? "").trim().replace(WRAPPING_QUOTES, "");
}

export function buildMailtoHref(
  email: string,
  options?: {
    subject?: string | null;
    body?: string | null;
  }
) {
  const target = cleanMailtoField(email);
  const subject = cleanMailtoField(options?.subject);
  const body = cleanMailtoField(options?.body);
  const queryParts: string[] = [];

  if (subject) {
    queryParts.push(`subject=${encodeURIComponent(subject)}`);
  }

  if (body) {
    queryParts.push(`body=${encodeURIComponent(body)}`);
  }

  return `mailto:${target}${queryParts.length ? `?${queryParts.join("&")}` : ""}`;
}
